insert into catalog.institutions(id,country_code,canonical_name,institution_type,website_url,status,slug,institution_kind,ownership_type,created_at,updated_at)
select md5('AE|program-provider|'||slug)::uuid,'AE',name,null,website,'active',slug,kind,null,now(),now()
from providers p
where not exists(select 1 from catalog.institutions i where i.country_code='AE' and i.slug=p.slug);

