insert into catalog.institution_identifiers(institution_id,identifier_system,identifier_value,source_url,valid_from)
select i.id,p.identifier_system,p.identifier_value,p.source_url,'2026-08-09'::date
from providers p join catalog.institutions i on i.country_code='AE' and i.slug=p.slug
on conflict(identifier_system,identifier_value) do update set institution_id=excluded.institution_id,source_url=excluded.source_url,valid_from=excluded.valid_from;

