insert into catalog.campuses(id,institution_id,name,city,region,country_code,status,locality,official_url,source_url,source_checked_at,metadata)
select md5('AE|program-provider-campus|'||p.slug)::uuid,i.id,'Primary program publication location',p.city,null,'AE','active',p.city,p.website,p.source_url,'2026-08-09'::timestamptz,jsonb_build_object('scope','program-provider-publication-location','complete_campus_inventory',false)
from providers p join catalog.institutions i on i.country_code='AE' and i.slug=p.slug
where not exists(select 1 from catalog.campuses c where c.id=md5('AE|program-provider-campus|'||p.slug)::uuid);

