insert into public.program_catalog_ae_staging(
 source_name,source_program_key,institution_name,institution_id,title,programme_level,credential_type,education_level,field_name,emirate,city,duration_years,tuition_fee_aed,official_program_url,caa_detail_url,source_url,source_as_of,accreditation_status,collection_status,verification_tier
)
select s.source_name,s.source_program_key,s.institution_name,i.id,s.title,s.programme_level,s.credential_type,s.programme_level,s.field_name,s.emirate,s.city,s.duration_years,s.tuition_fee_aed,s.official_program_url,s.caa_detail_url,s.source_url,s.source_as_of::date,'active',s.collection_status,s.verification_tier
from seed s join catalog.institutions i on i.country_code='AE' and i.canonical_name=s.institution_name
on conflict(source_name,source_program_key) do update set
 institution_name=excluded.institution_name,institution_id=excluded.institution_id,title=excluded.title,programme_level=excluded.programme_level,credential_type=excluded.credential_type,
 education_level=excluded.education_level,field_name=excluded.field_name,emirate=excluded.emirate,city=excluded.city,duration_years=excluded.duration_years,
 tuition_fee_aed=excluded.tuition_fee_aed,official_program_url=excluded.official_program_url,caa_detail_url=excluded.caa_detail_url,source_url=excluded.source_url,
 source_as_of=excluded.source_as_of,accreditation_status='active',collection_status=excluded.collection_status,verification_tier=excluded.verification_tier,collected_at=now();

insert into public.program_international_ae_staging(program_catalog_id,source_as_of,verification_status,rule_notes)
select p.id,'2026-08-09'::date,'unverified','No programme-level international admission inference; awaiting provider evidence.'
from public.program_catalog_ae_staging p
on conflict(program_catalog_id) do nothing;
